<script>
 import {tick,onMount} from 'svelte';
 import Icon from './Icon.svelte';
 import IconPicker from './IconPicker.svelte';
 import {reveal} from './motion.js';
 import {matches} from './shortcuts.js';
 import {ancestry,slotPosition,slotAt,CELL_HEIGHT,CELL_WIDTH} from './desktop.js';
 let {state:desktopState,folderId,areaHeight,motion,apps,showStatus,observation,statusLabel,statusDetail,onopen,onmutate,onupload,onerror,busy='',unavailable=false}=$props();
 let grid,menuNode=$state(),dialogNode=$state(),menu=$state(null),editor=$state(null),name=$state(''),address=$state(''),destination=$state(''),chosen=$state(null),file=$state(null),preview=$state(''),saving=$state(false),message=$state(''),gesture=$state(null),suppressClick=false,returnFocus;
 let selected=$state([]),anchor=$state(null),sortOpen=$state(false),sortTimer,selectionScope='';
 let rows=$derived(Math.max(1,Math.floor((areaHeight-30)/CELL_HEIGHT)));
 let visible=$derived(unavailable?[]:desktopState.items.filter(i=>i.parentId===folderId));
 let maxSlot=$derived(Math.max(0,...visible.map(i=>i.slot)));
 let context=$derived(folderId?'folder':'desktop');
 let folders=$derived(desktopState.items.filter(i=>i.kind==='folder'&&!moveIds().some(id=>id===i.id||ancestry(desktopState.items,i.id)?.some(p=>p.id===id))));
 $effect(()=>{const scope=desktopState.ownerId+':'+folderId+':'+unavailable;const allowed=new Set(visible.map(i=>i.id));if(selectionScope!==scope){selectionScope=scope;selected=[];anchor=null;gesture=null;menu=null;editor=null;clearPreview();}else {if(selected.some(id=>!allowed.has(id)))selected=selected.filter(id=>allowed.has(id));if(gesture?.ids?.some(id=>!allowed.has(id)))gesture=null;if(editor?.ids?.some(id=>!allowed.has(id))||editor?.item&&!allowed.has(editor.item.id)&&editor.kind!=='remove'){dialogNode?.close();editor=null;clearPreview();}if(menu?.item&&!allowed.has(menu.item.id))menu=null;}});
 function moveIds(){return editor?.kind==='moveGroup'?editor.ids:editor?.item?[editor.item.id]:selected;}
 function choose(e,item){if(suppressClick)return;if(e.shiftKey||e.ctrlKey||e.metaKey){selected=selected.includes(item.id)?selected.filter(id=>id!==item.id):[...selected,item.id];}else selected=[item.id];anchor=item.id;}
 function openFocused(e,item){if(suppressClick||e.shiftKey||e.ctrlKey||e.metaKey)return;onopen(item);}
 async function showMenu(e,item=null){e.preventDefault();e.stopPropagation();if(e.ctrlKey&&e.button!==2)return;if(item&&!selected.includes(item.id))selected=[item.id];returnFocus=e.target.closest('button')||grid;const b=returnFocus.getBoundingClientRect();sortOpen=false;menu={item,x:e.type==='keydown'?b.x:e.clientX,y:e.type==='keydown'?b.bottom:e.clientY};await tick();if(!menuNode)return;const r=menuNode.getBoundingClientRect();menu={...menu,x:Math.max(4,Math.min(menu.x,innerWidth-r.width-8)),y:Math.max(4,Math.min(menu.y,innerHeight-r.height-8))};menuNode.querySelector('button')?.focus();}
 function closeMenu(restore=true){clearTimeout(sortTimer);sortOpen=false;menu=null;if(restore)returnFocus?.focus();}
 async function revealSort(focus=false){clearTimeout(sortTimer);sortOpen=true;if(focus){await tick();menuNode?.querySelector('[aria-label="Sort order"] button')?.focus();}}
 function menuKeys(e){const submenu=e.target.closest('[aria-label="Sort order"]');if(matches('dismiss',e,'menu')||matches('menuTab',e,'menu')){e.preventDefault();closeMenu();return;}if(matches('submenu',e,'menu')&&e.target.dataset.sort){e.preventDefault();void revealSort(true);return;}if(matches('parentMenu',e,'menu')&&submenu){e.preventDefault();sortOpen=false;menuNode.querySelector('[data-sort]').focus();return;}const scope=submenu||menuNode;const buttons=[...scope.querySelectorAll('button')].filter(b=>!b.closest('[aria-label="Sort order"]')||submenu);const index=buttons.indexOf(document.activeElement);const next=matches('menuNext',e,'menu'),prev=matches('menuPrevious',e,'menu'),first=matches('menuFirst',e,'menu'),last=matches('menuLast',e,'menu');if(next||prev||first||last){e.preventDefault();buttons[first?0:last?buttons.length-1:(index+(next?1:-1)+buttons.length)%buttons.length]?.focus();}}
 async function sort(by){closeMenu();try{await onmutate('/desktop/sort','POST',{revision:desktopState.revision,parentId:folderId,by});}catch(e){onerror(e.message);}}
 async function edit(kind,item=null){closeMenu(false);editor={kind,item,ids:kind==='moveGroup'?[...selected]:undefined,sourceParentId:folderId};name=item?.label||'';destination=item?.parentId||'';chosen=item?.icon?.type==='builtin'?item.icon.name:undefined;file=null;message='';clearPreview();await tick();if(!dialogNode)return;dialogNode.showModal();dialogNode.querySelector('input,select,button')?.focus();}
 export function newFolder(){returnFocus=document.activeElement;void edit('create');}
 export function addApp(){returnFocus=document.activeElement;address='';void edit('bookmark');}
 export function unavailableShortcuts(){returnFocus=document.activeElement;void edit('cleanup');}
 function clearPreview(){if(preview)URL.revokeObjectURL(preview);preview='';}
 function cancel(){if(saving)return;dialogNode?.close();editor=null;clearPreview();returnFocus?.focus();}
 async function submit(){if(saving)return;saving=true;message='';try{const {kind,item}=editor;if(kind==='bookmark')await onmutate('/desktop/bookmarks','POST',{parentId:folderId,label:name,url:address,icon:chosen||'pixel-bookmark'});else if(kind==='create')await onmutate('/desktop/folders','POST',{parentId:folderId,label:name});else if(kind==='rename')await onmutate('/desktop/items/'+item.id,'PATCH',{label:name});else if(kind==='moveGroup')await onmutate('/desktop/move','POST',{revision:desktopState.revision,sourceParentId:editor.sourceParentId,itemIds:editor.ids,parentId:destination||null});else if(kind==='move')await onmutate('/desktop/items/'+item.id,'PATCH',{parentId:destination||null});else if(kind==='remove')await onmutate('/desktop/items/'+item.id,'DELETE');else if(kind==='icon'){if(file)await onupload(item.id,file);else if(chosen!==undefined)await onmutate('/desktop/items/'+item.id,'PATCH',{icon:chosen?{type:'builtin',name:chosen}:null});}saving=false;cancel();}catch(e){message=e.message;}finally{saving=false;}}
 function upload(e){message='';const value=e.target.files[0];if(!value)return;if(!['image/png','image/jpeg','image/webp'].includes(value.type)||value.size>1024*1024){message='Choose a PNG, JPEG or WebP image up to 1 MiB.';e.target.value='';return;}clearPreview();file=value;preview=URL.createObjectURL(value);}
 async function reset(item){closeMenu();try{await onmutate('/desktop/items/'+item.id,'PATCH',{label:null,icon:null});}catch(e){onerror(e.message);}}
 function start(e,item){if(e.button!==0||saving)return;if(e.shiftKey||e.ctrlKey||e.metaKey)choose(e,item);gesture={id:item.id,ids:selected.includes(item.id)?[...selected]:[item.id],sourceParentId:folderId,revision:desktopState.revision,x:e.clientX,y:e.clientY,active:false};e.currentTarget.setPointerCapture(e.pointerId);}
 function startMarquee(e){if(e.button!==0||e.target.closest('button,a')||unavailable)return;grid.focus();if(!e.shiftKey&&!e.ctrlKey&&!e.metaKey)selected=[];gesture={marquee:true,x:e.clientX,y:e.clientY,endX:e.clientX,endY:e.clientY,initial:e.shiftKey||e.ctrlKey||e.metaKey?[...selected]:[],active:false};grid.setPointerCapture(e.pointerId);}
 function drag(e){if(!gesture)return;if(Math.hypot(e.clientX-gesture.x,e.clientY-gesture.y)>7||gesture.active){gesture={...gesture,active:true,endX:e.clientX,endY:e.clientY};if(gesture.marquee){const x1=Math.min(gesture.x,e.clientX),x2=Math.max(gesture.x,e.clientX),y1=Math.min(gesture.y,e.clientY),y2=Math.max(gesture.y,e.clientY);selected=[...new Set([...gesture.initial,...[...grid.querySelectorAll('[data-item-id]')].filter(el=>{const r=el.getBoundingClientRect();return r.left<x2&&r.right>x1&&r.top<y2&&r.bottom>y1;}).map(el=>el.dataset.itemId)])];}else selected=gesture.ids;}}
 async function drop(e){if(!gesture)return;const g=gesture;gesture=null;if(!g.active)return;suppressClick=true;setTimeout(()=>suppressClick=false,0);if(g.marquee)return;const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-item-id]');const folder=desktopState.items.find(i=>i.id===target?.dataset.itemId&&i.kind==='folder'&&!g.ids.includes(i.id));const rect=grid.getBoundingClientRect();const slot=slotAt(e.clientX-rect.x+grid.scrollLeft-CELL_WIDTH/2,e.clientY-rect.y+grid.scrollTop-45,rows);try{if(g.ids.length===1)await onmutate('/desktop/items/'+g.id,'PATCH',folder?{parentId:folder.id}:{slot});else await onmutate('/desktop/move','POST',{revision:g.revision,sourceParentId:g.sourceParentId,itemIds:g.ids,parentId:folder?.id??folderId,...(!folder?{slot}:{} )});}catch(e){onerror(e.message);}}
 function keys(e){if(e.target.closest('input,select,textarea,[contenteditable=true]')||editor)return;const item=visible.find(i=>i.id===e.target.closest('[data-item-id]')?.dataset.itemId);if(matches('selectAll',e,context)){e.preventDefault();selected=visible.map(i=>i.id);}else if(matches('clear',e,context)){e.preventDefault();selected=[];}else if(matches('move',e,context)&&selected.length){e.preventDefault();returnFocus=document.activeElement;void edit('moveGroup');}else if(matches('open',e,context)&&item){e.preventDefault();onopen(item);}else if(matches('select',e,context)&&item){e.preventDefault();selected=selected.includes(item.id)?selected.filter(id=>id!==item.id):[...selected,item.id];}else if(matches('menu',e,context)||matches('menuAlt',e,context))showMenu(e,item);}
 onMount(()=>{const outside=e=>{if(menu&&!menuNode?.contains(e.target))closeMenu(false);};window.addEventListener('pointerdown',outside);return()=>{window.removeEventListener('pointerdown',outside);clearTimeout(sortTimer);clearPreview();};});
</script>
<!-- svelte-ignore a11y_no_noninteractive_tabindex, a11y_no_noninteractive_element_interactions -->
<section class="desktop-grid" bind:this={grid} tabindex="0" aria-label="Desktop items" oncontextmenu={e=>showMenu(e)} onkeydown={keys} onpointerdown={startMarquee} onpointermove={drag} onpointerup={drop} onpointercancel={()=>gesture=null}>
 {#if unavailable}<div class="desktop-unavailable"><p>This location is unavailable.</p><a href="/desktop" onclick={e=>{if(!e.metaKey&&!e.ctrlKey&&!e.shiftKey&&!e.altKey&&e.button===0){e.preventDefault();onopen(null);}}}>Return to home</a></div>
 {:else}<div class="grid-extent" style:width={Math.max(1,Math.floor(maxSlot/rows)+1)*CELL_WIDTH+36+'px'} style:height={rows*CELL_HEIGHT+24+'px'}></div>
 {#each visible as item,i (item.id)}
 {@const pos=slotPosition(item.slot,rows)}{@const app=apps.find(a=>a.id===item.appId)}
 <button class="shortcut desktop-shortcut" class:selected={selected.includes(item.id)} class:dragging={gesture?.ids?.includes(item.id)&&gesture?.active} data-item-id={item.id} style:left={pos.x+'px'} style:top={pos.y+'px'} use:reveal={{enabled:motion,delay:Math.min(i,6)*25,kind:'slide'}} aria-label={'Open '+item.label} aria-pressed={selected.includes(item.id)} aria-describedby={app&&showStatus?'health-'+app.id:undefined} disabled={busy===item.appId} onclick={e=>{if(e.detail===0)onopen(item);else if(!e.shiftKey&&!e.ctrlKey&&!e.metaKey)choose(e,item);}} ondblclick={e=>openFocused(e,item)} oncontextmenu={e=>showMenu(e,item)} onpointerdown={e=>start(e,item)} title={app&&showStatus?statusDetail(observation(app)):item.label}>
 {#if item.icon?.type==='upload'}<img src={item.icon.url} alt="" draggable="false"/>{:else}<Icon name={item.icon?.name||'pixel-folder'}/>{/if}<span>{item.label}</span><small>{item.kind==='folder'?'folder':app?.kind==='system'?'system':app?.mode==='gateway'?'gateway · experimental':app?.mode==='stream'?'streamed':app?.openMode==='tab'?'native · new tab':'native'}</small>
 {#if app&&showStatus}<small id={'health-'+app.id} class="health"><i class:online={observation(app)?.reachability==='responding'} class:offline={observation(app)?.reachability==='unreachable'}></i>{statusLabel(observation(app))}<span class="health-detail">{statusDetail(observation(app))}</span></small>{/if}
 </button><button class="item-actions" aria-label={'Actions for '+item.label} style:left={pos.x+76+'px'} style:top={pos.y+'px'} onclick={e=>showMenu(e,item)}>⋯</button>{/each}{/if}
 {#if selected.length}<aside class="selection-tools" aria-label="Selection"><span role="status">{selected.length} selected</span><button onclick={()=>{returnFocus=document.activeElement;void edit('moveGroup');}}>Move selection…</button><button onclick={()=>selected=[]}>Clear selection</button></aside>{/if}
</section>
{#if gesture?.marquee&&gesture.active}<div class="marquee" style:left={Math.min(gesture.x,gesture.endX)+'px'} style:top={Math.min(gesture.y,gesture.endY)+'px'} style:width={Math.abs(gesture.x-gesture.endX)+'px'} style:height={Math.abs(gesture.y-gesture.endY)+'px'}></div>{/if}
{#if menu}
 <!-- svelte-ignore a11y_no_noninteractive_element_interactions -->
 <div class="desktop-context" role="menu" tabindex="-1" aria-label="Desktop actions" bind:this={menuNode} style:left={menu.x+'px'} style:top={menu.y+'px'} onkeydown={menuKeys}>
 {#if menu.item}{@const item=menu.item}<button role="menuitem" onclick={()=>{closeMenu();onopen(item);}}>Open</button><button role="menuitem" onclick={()=>edit('rename',item)}>Rename</button><button role="menuitem" onclick={()=>edit('icon',item)}>Change icon</button><button role="menuitem" onclick={()=>edit('move',item)}>Move to…</button>{#if selected.length>1}<button role="menuitem" onclick={()=>edit('moveGroup')}>Move selection…</button>{/if}{#if item.kind==='folder'}<button role="menuitem" onclick={()=>edit('remove',item)}>Remove folder</button>{:else}<button role="menuitem" onclick={()=>reset(item)}>Reset appearance</button>{#if apps.find(a=>a.id===item.appId)?.personal}<button role="menuitem" onclick={()=>edit('remove',item)}>Remove shortcut</button>{/if}{/if}{:else}<button role="menuitem" onclick={addApp}>Add app</button><button role="menuitem" onclick={()=>edit('create')}>New folder</button>{/if}
 <div class="sort-holder" role="presentation" onpointerenter={()=>revealSort()} onpointerleave={()=>{sortTimer=setTimeout(()=>{if(!menuNode?.querySelector('.sort-holder')?.contains(document.activeElement))sortOpen=false;},250);}}><button data-sort="true" role="menuitem" aria-haspopup="menu" aria-expanded={sortOpen} onclick={()=>revealSort(true)} onfocus={()=>revealSort()}>Sort by ›</button>{#if sortOpen}<div role="menu" aria-label="Sort order"><button role="menuitem" onclick={()=>sort('name')}>Name</button><button role="menuitem" onclick={()=>sort('type')}>Type</button></div>{/if}</div>
 </div>{/if}
{#if editor}
 <dialog class="desktop-dialog" bind:this={dialogNode} aria-label={editor.kind==='icon'?'Change icon':'Desktop item'} oncancel={e=>{e.preventDefault();cancel();}}>
 <form onsubmit={e=>{e.preventDefault();submit();}}><h2>{editor.kind==='cleanup'?'Unavailable shortcuts':editor.kind==='bookmark'?'Add personal app':editor.kind==='create'?'New folder':editor.kind==='rename'?'Rename':editor.kind==='move'||editor.kind==='moveGroup'?'Move to…':editor.kind==='remove'?(editor.item.kind==='folder'?'Remove folder':'Remove shortcut'):'Change icon'}</h2>
 {#if editor.kind==='cleanup'}<p>These private shortcuts cannot launch under the current hostname policy. Removing one frees its personal quota; no upstream site or shared app is deleted.</p>{#each desktopState.unavailablePersonalItems||[] as item}<p><span>{item.label}</span> <button type="button" aria-label={'Remove '+item.label} onclick={()=>edit('remove',{...item,kind:'app'})}>Remove shortcut…</button></p>{/each}
 {:else if editor.kind==='bookmark'}<label>Name<input bind:value={name} required maxlength="64"/></label><label>URL<input type="url" bind:value={address} required maxlength="2048" placeholder="https://example.com/"/></label><IconPicker selected={chosen||'pixel-bookmark'} onchoose={id=>chosen=id}/><p class="dialog-hint">Private Native shortcut only. The site opens on your device; embedding may be blocked. Open in new tab is always available. Upload a private image later with Change icon.</p>
 {:else if editor.kind==='create'||editor.kind==='rename'}<label>{editor.kind==='create'?'Folder name':'Name'}<input bind:value={name} required maxlength="64"/></label>
 {:else if editor.kind==='move'||editor.kind==='moveGroup'}<label>Destination<select bind:value={destination}><option value="">~ (home)</option>{#each folders as f}<option value={f.id}>{ancestry(desktopState.items,f.id)?.map(p=>p.label).join(' / ')}</option>{/each}</select></label>
 {:else if editor.kind==='remove'}<p>Remove “{editor.item.label}”? {editor.item.kind==='folder'?'Contents move up one level. Apps and their data are not deleted.':'Only your personal shortcut is removed. The upstream site and shared apps are unchanged.'}</p>
 {:else}<div class="icon-preview">{#if preview}<img src={preview} alt="Selected icon preview"/>{:else if chosen===undefined&&editor.item.icon?.type==='upload'}<img src={editor.item.icon.url} alt="Current icon preview"/>{:else}<Icon name={chosen||(editor.item.kind==='folder'?'pixel-folder':apps.find(a=>a.id===editor.item.appId)?.icon)||'globe'}/>{/if}</div><IconPicker choices={desktopState.iconChoices} selected={!file?chosen:null} onchoose={id=>{chosen=id;file=null;clearPreview();}}/><label>Upload icon<input type="file" accept="image/png,image/jpeg,image/webp" onchange={upload}/></label><p class="dialog-hint">PNG, JPEG or WebP · up to 1 MiB. Saved privately as a small PNG.</p>{#if editor.item.kind==='app'}<button type="button" onclick={()=>{chosen=null;file=null;clearPreview();}}>Use app default</button>{/if}{/if}
 {#if message}<p role="alert">{message}</p>{/if}<div class="dialog-actions"><button type="button" disabled={saving} onclick={cancel}>Cancel</button>{#if editor.kind!=='cleanup'}<button disabled={saving} type="submit">{saving?'Saving…':editor.kind==='bookmark'?'Add app':editor.kind==='create'?'Create folder':editor.kind==='icon'?'Save icon':editor.kind==='remove'?(editor.item.kind==='folder'?'Remove folder':'Remove shortcut'):'Save'}</button>{/if}</div></form>
 </dialog>{/if}
<style>
 .health i{background:#78716c}.health i.online{background:#a8a29e}.health i.offline{background:#b65c54}
 .item-actions{position:absolute;width:28px;height:28px;color:#a8a29e;background:#0c0a09}.item-actions:hover,.item-actions:focus-visible{color:#fafaf9;background:#292524}
 .desktop-grid{position:absolute;inset:0;overflow:auto;outline-offset:-2px;touch-action:none}.grid-extent{pointer-events:none}.desktop-shortcut{position:absolute;width:100px;height:120px;gap:5px;touch-action:none;user-select:none}.desktop-shortcut.selected{background:#fafaf91a;outline:1px solid #e7e5e4}.desktop-shortcut>span{max-width:106px;overflow-wrap:anywhere;max-height:36px;overflow:hidden;font-size:12px}.desktop-shortcut img{width:43px;height:43px;object-fit:contain}.desktop-shortcut.dragging{opacity:.5;outline:1px dashed #a8a29e}.desktop-context{position:fixed;z-index:1800;min-width:175px;max-width:calc(100vw - 16px);max-height:calc(100dvh - 16px);overflow:auto;padding:5px;background:#1c1917;border:1px solid #a8a29e;box-shadow:4px 4px #0008}.desktop-context button{display:block;text-align:left;width:100%;padding:10px 12px}.desktop-context button:hover,.desktop-context button:focus{background:#44403c;outline-offset:-2px}.sort-holder [role=menu]{margin-left:12px;border-left:1px solid #78716c}.desktop-dialog{width:min(540px,calc(100vw - 24px));max-height:calc(100dvh - 40px);overflow:auto;background:#1c1917;color:#fafaf9;border:1px solid #a8a29e;padding:22px;font:inherit}.desktop-dialog::backdrop{background:#0009}.desktop-dialog h2{font-size:16px;margin:0 0 20px}.desktop-dialog label{display:block;margin:12px 0}.desktop-dialog input,.desktop-dialog select{display:block;width:100%;background:#0c0a09;color:#fafaf9;border:1px solid #78716c;padding:10px;margin-top:8px;font:inherit}.desktop-dialog button{padding:9px 12px;border:1px solid #78716c}.dialog-actions{display:flex;justify-content:flex-end;gap:12px;margin-top:24px}.icon-preview{height:64px;margin-bottom:16px}.icon-preview :global(svg),.icon-preview img{width:64px;height:64px;object-fit:contain}.dialog-hint{color:#a8a29e;font-size:11px}.desktop-unavailable{padding:30px}.desktop-unavailable a{color:inherit}.selection-tools{position:sticky;bottom:8px;left:20px;width:max-content;max-width:100%;padding:10px;background:#1c1917;border:1px solid #78716c;display:flex;gap:14px;z-index:3}.marquee{position:fixed;pointer-events:none;z-index:8;border:1px solid #e7e5e4;background:#fafaf91a}
</style>
